mapper.select:
        select pay.id,
		ifnull(
			(SELECT e2.paydate FROM t_erp_purchase_form_entry_alibabainfo_ext e2 WHERE e2.entryid = pay.formentryid LIMIT 1),
			pay.opttime
		) opttime,pay.payprice,form.number,entry.paystatus,entry.totalin,
        form.createdate,m.sku,
		p.location image,m.name mname,entry.amount purchases,w.name wname,c.name cname,
		tp.name fee_type ,
		pay.remark,
		entry.orderprice,
		pmd.name payment_method,fa.name acctname,pay.acct,entry.totalpay,
		(entry.orderprice-entry.totalpay) need_pay,
		u.name,
		gp.name groupname
		from t_erp_purchase_form_payment pay
        left join t_erp_purchase_form_payment_method pmd on pmd.id=pay.payment_method
		left join t_erp_fin_project tp on tp.id=pay.projectid  
		left join t_erp_purchase_form_entry entry on entry.id=pay.formentryid
		left join t_userinfo u on u.id=pay.operator
		left join t_erp_material m on m.id=entry.materialid
		left join t_amazon_group gp on gp.id=m.groupid
		left join t_erp_purchase_form form on form.id=entry.formid 
		left join t_erp_customer c on c.id=entry.supplier
        left join t_picture p on p.id=m.image
        left join t_erp_warehouse w on w.id=form.warehouseid
		left join t_erp_fin_account fa on fa.id=pay.acct
	where  form.shopid=#{param.shopid,jdbcType=CHAR}   and pay.auditstatus=1

	and pay.period_rollover_id IS NULL


	and pay.acct = #{param.acct,jdbcType=CHAR}


	  and EXISTS (
		SELECT 1 FROM t_erp_purchase_form_entry_alibabainfo_ext e2 
		INNER JOIN t_erp_purchase_alibaba_settlement_order o2 ON o2.orderid = e2.alibaba_orderid
		INNER JOIN t_erp_purchase_alibaba_settlement st2 ON st2.id = o2.settlementid
		WHERE e2.entryid = pay.formentryid 
		AND o2.settlementid = #{param.settlementid,jdbcType=CHAR}
		AND st2.acct = pay.acct
	  )


		and entry.auditstatus>1 

		and pay.createdate >=#{param.fromDate,jdbcType=DATE}
	    and pay.createdate <=#{param.endDate,jdbcType=DATE} 


		and EXISTS (
			SELECT 1 FROM t_erp_purchase_form_entry_alibabainfo_ext e2 
			WHERE e2.entryid = pay.formentryid 
			AND e2.paydate >= #{param.fromDate,jdbcType=DATE}
			AND e2.paydate <= #{param.endDate,jdbcType=DATE}
		)


		and EXISTS (
			SELECT 1 FROM t_erp_purchase_form_entry_alibabainfo_ext e2 
			WHERE e2.entryid = pay.formentryid 
			AND e2.countdate >= #{param.fromDate,jdbcType=DATE}
			AND e2.countdate <= #{param.endDate,jdbcType=DATE}
		)





    			and	m.sku like #{param.search,jdbcType=CHAR}


    			 and (form.number like #{param.search,jdbcType=CHAR} )


    			 and pay.remark like CONCAT('%',#{param.search,jdbcType=CHAR})


    			 and EXISTS (
					SELECT 1 FROM t_erp_purchase_form_entry_alibabainfo_ext e2 
					INNER JOIN t_erp_purchase_alibaba_settlement_order o2 ON o2.orderid = e2.alibaba_orderid
					WHERE e2.entryid = pay.formentryid 
					AND o2.orderid like #{param.search,jdbcType=CHAR}
				)




    			 and   pay.projectid= #{param.projectid,jdbcType=CHAR} 


    			 and   form.warehouseid= #{param.warehouseid,jdbcType=CHAR} 


    			 and   entry.supplier= #{param.supplierid,jdbcType=CHAR} 


    			 and   pay.payment_method= #{param.paymethod,jdbcType=CHAR} 


    			 and   m.groupid= #{param.groupid,jdbcType=CHAR}

