SELECT pay.id
FROM t_erp_purchase_form_payment pay
INNER JOIN t_erp_purchase_form_entry entry ON entry.id = pay.formentryid
INNER JOIN t_erp_purchase_form form ON form.id = entry.formid
WHERE form.shopid = #{param.shopid}
  AND pay.auditstatus = 1
  AND pay.period_rollover_id IS NULL
  AND pay.acct = #{param.acct}
  AND entry.auditstatus > 1



      AND EXISTS (
        SELECT 1 FROM t_erp_purchase_form_entry_alibabainfo_ext e2
        WHERE e2.entryid = pay.formentryid
        AND e2.paydate >= #{param.fromDate,jdbcType=DATE}
        AND e2.paydate <= #{param.endDate,jdbcType=DATE}
      )


      AND EXISTS (
        SELECT 1 FROM t_erp_purchase_form_entry_alibabainfo_ext e2
        WHERE e2.entryid = pay.formentryid
        AND e2.countdate >= #{param.fromDate,jdbcType=DATE}
        AND e2.countdate <= #{param.endDate,jdbcType=DATE}
      )


      AND pay.opttime >= #{param.fromDate,jdbcType=DATE}
      AND pay.opttime <= #{param.endDate,jdbcType=DATE}

SELECT pay.id
FROM t_erp_purchase_form_payment pay
INNER JOIN t_erp_purchase_form_entry entry ON entry.id = pay.formentryid
INNER JOIN t_erp_purchase_form form ON form.id = entry.formid
INNER JOIN t_erp_material m ON m.id = entry.materialid
WHERE form.shopid = #{param.shopid}
  AND pay.auditstatus = 1
  AND pay.period_rollover_id IS NULL
  AND pay.acct = #{param.acct}
  AND entry.auditstatus > 1
  AND form.number = #{param.orderId}
  AND m.sku = #{param.sku}
